import{_ as o,c as a,o as c,ae as t}from"./chunks/framework.DEXG3EuZ.js";const m=JSON.parse('{"title":"コマース実装例","description":"","frontmatter":{},"headers":[],"relativePath":"ja/guide/commerce.md","filePath":"ja/guide/commerce.md","lastUpdated":1792605191000}'),d={name:"ja/guide/commerce.md"};function i(n,e,s,p,r,l){return c(),a("div",null,[...e[0]||(e[0]=[t(`<h1 id="コマース実装例" tabindex="-1">コマース実装例 <a class="header-anchor" href="#コマース実装例" aria-label="Permalink to &quot;コマース実装例&quot;">​</a></h1><ul><li><code>/shop</code>: 公開商品一覧、検索、カテゴリ、並び替え、Infinite Query。</li><li><code>/shop/products/:id</code>: 3言語詳細、数量、Safe Area 対応購入バー。</li><li><code>/shop/admin/products</code>: admin の商品作成、編集、公開状態、論理削除。</li></ul><p>契約は OpenAPI から生成し、金額は整数の最小通貨単位で保存します。商品名、特徴、説明は <code>zh-CN</code>、<code>en-US</code>、<code>ja-JP</code> が必須です。画像 URL は同一 Origin または HTTPS だけを許可します。</p><p><code>pnpm dev</code> は Mock、<code>pnpm dev:integration</code> は Gin/FastAPI のプロキシを設定します。実サービスを使う前に、以下の契約の差を確認してください。Remote State は TanStack Query が管理し、Pinia には保存しません。</p><h2 id="お気に入り操作とセッションの分離" tabindex="-1">お気に入り操作とセッションの分離 <a class="header-anchor" href="#お気に入り操作とセッションの分離" aria-label="Permalink to &quot;お気に入り操作とセッションの分離&quot;">​</a></h2><p><code>FavoriteButton</code> に数値の <code>productId</code> と現在の <code>session</code> トークンを渡します。未ログイン時はログインリンクを表示し、非公開の状態を取得しません。ログイン後は保存済みの状態を読み込んでから操作を有効にします。取得失敗時は再試行でき、保存失敗時は最後に確認した状態を保ってエラーを表示します。取得・保存中の二重送信を防ぎます。</p><p>状態は TanStack Query が管理します。キーはコントロールのインスタンス、セッションの世代、商品 ID から構成し、トークンを含めません。更新時に元のキーを保持するため、古い応答が別のアカウントや商品の状態を上書きしません。再マウントやセッション変更で再取得します。サーバーに状態の反転を依頼せず、明示的な真偽値を送ります。</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>GET  /api/product/favorite?id=1</span></span>
<span class="line"><span>POST /api/product/favorite</span></span>
<span class="line"><span>{ &quot;productId&quot;: 1, &quot;favorite&quot;: true }</span></span></code></pre></div><p><code>src/components/shop/FavoriteButton.vue</code> → <code>src/api/modules/favorites.ts</code> → <code>apiClient</code>.</p><p>応答の包装への対応は、パスや商品フィールドの変換を意味しません。単体アプリの商品 API は <code>/api/products</code> と多言語 <code>name</code>／<code>priceCents</code>、現在の Gin は <code>/api/product/list</code> と <code>title</code>／<code>price</code> です。ログインにも <code>name</code>／<code>token</code> と <code>username</code>／<code>accessToken</code> の差があります。全面的な連携を確認する前に契約を照合するか、明示的なドメインアダプターを追加してください。新しいお気に入りパスは Gin に一致しますが、認証には互換性のある発行済み JWT が必要です。</p><h2 id="商品リンクとページの再利用" tabindex="-1">商品リンクとページの再利用 <a class="header-anchor" href="#商品リンクとページの再利用" aria-label="Permalink to &quot;商品リンクとページの再利用&quot;">​</a></h2><p>詳細ページでは JavaScript の安全な整数範囲に収まる、正の十進整数 ID のみを受け付けます。ID の欠落、重複、負数、小数、指数表記、範囲超過は詳細 API を呼ばず、無効なリンクの案内と商品一覧へのリンクを表示します。</p><p>同じコンポーネントで商品が切り替わると、数量を 1 に戻し、前の商品の操作結果を消去します。在庫の更新時は数量を在庫範囲に収め、在庫切れや販売対象外の商品では購入と数量の操作を無効にします。詳細データは引き続き TanStack Query が管理して <code>AbortSignal</code> を渡し、カートに別のサーバーキャッシュを作りません。</p><p><a href="./request">API</a> · <a href="./testing">テスト</a></p>`,14)])])}const h=o(d,[["render",i]]);export{m as __pageData,h as default};
